640	/// Caches exported files so that we can avoid re-exporting them if they haven't
641	/// changed.
642	///
643	/// This is done by having a list of size `files.len()` that contains the hashes
644	/// of the last rendered frame in each file. If a new frame is inserted, this
645	/// will invalidate the rest of the cache, this is deliberate as to decrease the
646	/// complexity and memory usage of such a cache.
647	pub struct ExportCache {
648	    /// The hashes of last compilation's frames.
649	    pub cache: RwLock<Vec<u128>>,
650	}
651	
652	impl ExportCache {
653	    /// Creates a new export cache.
654	    pub fn new() -> Self {
655	        Self { cache: RwLock::new(Vec::with_capacity(32)) }
656	    }
657	
658	    /// Returns true if the entry is cached and appends the new hash to the
659	    /// cache (for the next compilation).
660	    pub fn is_cached(&self, i: usize, page: &Page) -> bool {
661	        let hash = typst::utils::hash128(page);
662	
663	        let mut cache = self.cache.upgradable_read();
664	        if i >= cache.len() {
665	            cache.with_upgraded(|cache| cache.push(hash));
666	            return false;
667	        }
668	
669	        cache.with_upgraded(|cache| std::mem::replace(&mut cache[i], hash) == hash)
670	    }
671	}
672	
673	/// Opens the output if desired.
674	fn open_output(config: &mut CompileConfig) -> StrResult<()> {
675	    let Some(viewer) = config.open.take() else { return Ok(()) };
676	
677	    #[cfg(feature = "http-server")]
678	    if let Some(server) = &config.server {
679	        let url = format!("http://{}", server.addr());
680	        return open_path(OsStr::new(&url), viewer.as_deref());
681	    }
682	
683	    // Can't open stdout.
684	    let Output::Path(path) = &config.output else { return Ok(()) };
685	
686	    // Some resource openers require the path to be canonicalized.
687	    let path = path
688	        .canonicalize()
689	        .map_err(|err| eco_format!("failed to canonicalize path ({err})"))?;
690	
691	    open_path(path.as_os_str(), viewer.as_deref())
692	}
693	
694	/// Opens the given file using:
695	///
696	/// - The default file viewer if `app` is `None`.
697	/// - The given viewer provided by `app` if it is `Some`.
698	fn open_path(path: &OsStr, viewer: Option<&str>) -> StrResult<()> {
699	    if let Some(viewer) = viewer {
700	        open::with_detached(path, viewer)
701	            .map_err(|err| eco_format!("failed to open file with {viewer} ({err})"))
702	    } else {
703	        open::that_detached(path).map_err(|err| {
704	            let openers = open::commands(path)
705	                .iter()
706	                .map(|command| command.get_program().to_string_lossy())
707	                .collect::<Vec<_>>()
708	                .join(", ");
709	            eco_format!(
710	                "failed to open file with any of these resource openers: {openers} \
711	                 ({err})",
712	            )
713	        })
714	    }
715	}
716	
717	/// Print diagnostic messages to the terminal.
718	pub fn print_diagnostics(
719	    world: &dyn DiagnosticWorld,
720	    errors: &[SourceDiagnostic],
721	    warnings: &[SourceDiagnostic],
722	    format: DiagnosticFormat,
723	) -> Result<(), codespan_reporting::files::Error> {
724	    typst_kit::diagnostics::emit(
725	        &mut terminal::out(),
726	        world,
727	        errors.iter().chain(warnings),
728	        match format {
729	            DiagnosticFormat::Human => typst_kit::diagnostics::DiagnosticFormat::Human,
730	            DiagnosticFormat::Short => typst_kit::diagnostics::DiagnosticFormat::Short,
731	        },
732	    )
733	}
734	
735	impl From<PdfStandard> for typst_pdf::PdfStandard {
736	    fn from(standard: PdfStandard) -> Self {
737	        match standard {
738	            PdfStandard::V_1_4 => typst_pdf::PdfStandard::V_1_4,
739	            PdfStandard::V_1_5 => typst_pdf::PdfStandard::V_1_5,
740	            PdfStandard::V_1_6 => typst_pdf::PdfStandard::V_1_6,
741	            PdfStandard::V_1_7 => typst_pdf::PdfStandard::V_1_7,
742	            PdfStandard::V_2_0 => typst_pdf::PdfStandard::V_2_0,
743	            PdfStandard::A_1b => typst_pdf::PdfStandard::A_1b,
744	            PdfStandard::A_1a => typst_pdf::PdfStandard::A_1a,
745	            PdfStandard::A_2b => typst_pdf::PdfStandard::A_2b,
746	            PdfStandard::A_2u => typst_pdf::PdfStandard::A_2u,
747	            PdfStandard::A_2a => typst_pdf::PdfStandard::A_2a,
748	            PdfStandard::A_3b => typst_pdf::PdfStandard::A_3b,
749	            PdfStandard::A_3u => typst_pdf::PdfStandard::A_3u,
750	            PdfStandard::A_3a => typst_pdf::PdfStandard::A_3a,
751	            PdfStandard::A_4 => typst_pdf::PdfStandard::A_4,
752	            PdfStandard::A_4f => typst_pdf::PdfStandard::A_4f,
753	            PdfStandard::A_4e => typst_pdf::PdfStandard::A_4e,
754	            PdfStandard::UA_1 => typst_pdf::PdfStandard::Ua_1,
755	        }
756	    }
757	}
