[dependencies.typst-kit]
workspace = true
features = [
    "bundle",
    "embedded-fonts",
    "scan-fonts",
    "system-packages",
    "universe-packages",
    "datetime",
    "emit-diagnostics",
    "system-downloader",
    "watcher",
    "timer",
]

[dev-dependencies]
typst-dev-assets = { workspace = true }
memchr = { workspace = true }
